```tsx
// src/components/ErrorBoundary.tsx
import { Component, type ErrorInfo, type ReactNode } from "react";

type FallbackRender = (error: Error, reset: () => void) => ReactNode;

interface Props {
  children: ReactNode;
  fallback?: ReactNode | FallbackRender;
}

interface State {
  error: Error | null;
  componentStack: string | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null, componentStack: null };

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo): void {
    console.error("[ErrorBoundary] Uncaught error:", error);
    console.error("[ErrorBoundary] Component stack:", info.componentStack);
    this.setState({ componentStack: info.componentStack ?? null });
  }

  reset = (): void => {
    this.setState({ error: null, componentStack: null });
  };

  render(): ReactNode {
    const { error, componentStack } = this.state;
    const { fallback, children } = this.props;

    if (!error) return children;

    if (typeof fallback === "function") {
      return (fallback as FallbackRender)(error, this.reset);
    }

    if (fallback !== undefined) return fallback;

    return (
      <div
        role="alert"
        style={{
          padding: "1rem",
          border: "1px solid #f87171",
          borderRadius: "4px",
          fontFamily: "sans-serif",
        }}
      >
        <h2 style={{ margin: "0 0 0.5rem" }}>Something went wrong</h2>
        <pre
          style={{
            whiteSpace: "pre-wrap",
            color: "#dc2626",
            margin: "0 0 0.75rem",
          }}
        >
          {error.message}
        </pre>
        {componentStack && (
          <details style={{ marginBottom: "0.75rem" }}>
            <summary style={{ cursor: "pointer", color: "#6b7280" }}>
              Component stack
            </summary>
            <pre style={{ whiteSpace: "pre-wrap", fontSize: "0.75rem" }}>
              {componentStack}
            </pre>
          </details>
        )}
        <button onClick={this.reset}>Try Again</button>
      </div>
    );
  }
}
```

**Key changes over the existing file:**

| What changed | Why |
|---|---|
| `fallback` accepts `FallbackRender` — `(error, reset) => ReactNode` | Callers can build their own UI with access to the error and the retry function |
| Static `fallback` node now shows when non-undefined (was checking truthiness, which would skip `0` or `""`) | Correctness |
| Default UI shows a collapsible `<details>` block with the component stack | Easier debugging without cluttering the visible UI |
| Two separate `console.error` calls with labelled prefixes | Error and stack are easier to scan in the console |

**Usage examples:**

```tsx
// Default fallback
<ErrorBoundary>
  <MyWidget />
</ErrorBoundary>

// Render-function fallback (has access to retry)
<ErrorBoundary
  fallback={(error, reset) => (
    <div>
      <p>Failed: {error.message}</p>
      <button onClick={reset}>Retry</button>
    </div>
  )}
>
  <MyWidget />
</ErrorBoundary>

// Static node (no retry)
<ErrorBoundary fallback={<p>Unavailable</p>}>
  <MyWidget />
</ErrorBoundary>
```

